 /** Selects paths with an ordered list of glob patterns. See README.md for the syntax. */
+
+/** One path segment of a compiled pattern: either a globstar or a per-segment regex. */
+type Part = "**" | RegExp;
+
+interface Rule {
+  /** The pattern exactly as it was given, including a leading `!`. */
+  raw: string;
+  negated: boolean;
+  parts: Part[];
+}
+
+/** Escapes a literal character for use inside a RegExp built with the `u` flag. */
+function escapeRegExp(ch: string): string {
+  return /[\\^$.*+?()[\]{}|/]/.test(ch) ? `\\${ch}` : ch;
+}
+
+/** Compiles one path segment (no `/` inside) into an anchored regex. */
+function compileSegment(segment: string): RegExp {
+  let source = "";
+  let previousWasStar = false;
+  for (const ch of segment) {
+    if (ch === "*") {
+      // A run of stars inside a segment behaves like a single `*`.
+      if (!previousWasStar) source += "[^/]*";
+      previousWasStar = true;
+      continue;
+    }
+    previousWasStar = false;
+    source += ch === "?" ? "[^/]" : escapeRegExp(ch);
+  }
+  return new RegExp(`^${source}$`, "u");
+}
+
+function compilePattern(raw: string): Rule {
+  const negated = raw.startsWith("!");
+  const body = negated ? raw.slice(1) : raw;
+  const parts: Part[] = body
+    .split("/")
+    .map((segment) => (segment === "**" ? "**" : compileSegment(segment)));
+  return { raw, negated, parts };
+}
